#!/bin/bash
set -e
cd /var/www/keystarter-frontend
mkdir -p assets
[ -f index.html ] && cp index.html index.html.bak2
echo Backup done

echo '' | base64 -d > index.html
echo 'index.html OK'

echo '' | base64 -d > assets/index-BVFQ89G8.css
echo 'assets/index-BVFQ89G8.css OK'

echo '' | base64 -d > assets/index-CzYpchmy.js
echo 'assets/index-CzYpchmy.js OK'

echo Deploy complete
